using UnityEngine;

/// <summary>
/// 그리드 위의 단일 타일
/// </summary>
public class Tile : MonoBehaviour
{
    public int x { get; private set; }
    public int z { get; private set; }

    // 현재 이 타일 위에 있는 유닛
    public Unit OccupiedUnit { get; set; }

    public bool IsOccupied => OccupiedUnit != null;

    // ── 타일 상태 ────────────────────────────────────────────────────
    public enum HighlightState { Normal, Selected, Moveable, Path }
    private HighlightState currentState = HighlightState.Normal;

    private Renderer tileRenderer;
    private static readonly int EmissionColor = Shader.PropertyToID("_EmissionColor");

    // 색상 (Inspector 에서 조정 가능 – GridManager 가 생성 시 할당)
    [HideInInspector] public Color colorNormal   = new Color(0.3f, 0.5f, 0.3f);
    [HideInInspector] public Color colorSelected = new Color(0.9f, 0.9f, 0.2f);
    [HideInInspector] public Color colorMoveable = new Color(0.2f, 0.6f, 0.9f);
    [HideInInspector] public Color colorPath     = new Color(0.4f, 0.9f, 0.5f);

    private Material mat;

    public void Init(int x, int z)
    {
        this.x = x;
        this.z = z;
        tileRenderer = GetComponentInChildren<Renderer>();
        if (tileRenderer != null)
        {
            mat = new Material(tileRenderer.sharedMaterial);
            tileRenderer.material = mat;
        }
        SetState(HighlightState.Normal);
    }

    public void SetState(HighlightState state)
    {
        currentState = state;
        ApplyColor();
    }

    void ApplyColor()
    {
        if (mat == null) return;
        Color c = currentState switch
        {
            HighlightState.Selected => colorSelected,
            HighlightState.Moveable => colorMoveable,
            HighlightState.Path     => colorPath,
            _                       => colorNormal,
        };
        mat.color = c;
    }

    public HighlightState CurrentState => currentState;

    /// <summary>타일 월드 중심 좌표 반환</summary>
    public Vector3 WorldCenter => transform.position;
}

