using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 정사각형 그리드를 생성하고 관리하는 매니저
/// GridManager.Instance 로 접근
/// </summary>
public class GridManager : MonoBehaviour
{
    public static GridManager Instance { get; private set; }

    [Header("Grid Size")]
    public int width  = 20;
    public int height = 20;

    [Header("Tile Settings")]
    public float tileSize   = 1f;
    public float tileHeight = 0.05f;   // 타일 두께
    public GameObject tilePrefab;      // null 이면 기본 Quad 생성

    [Header("Tile Colors")]
    public Color colorNormal   = new Color(0.35f, 0.55f, 0.35f);
    public Color colorSelected = new Color(0.95f, 0.90f, 0.15f);
    public Color colorMoveable = new Color(0.25f, 0.65f, 0.95f);
    public Color colorPath     = new Color(0.40f, 0.90f, 0.50f);

    // 내부 타일 배열
    private Tile[,] tiles;

    void Awake()
    {
        if (Instance != null && Instance != this) { Destroy(gameObject); return; }
        Instance = this;
        GenerateGrid();
    }

    // ── 그리드 생성 ──────────────────────────────────────────────────
    void GenerateGrid()
    {
        tiles = new Tile[width, height];

        for (int x = 0; x < width; x++)
        for (int z = 0; z < height; z++)
        {
            Vector3 pos = GridToWorld(x, z) + Vector3.up * (tileHeight * 0.5f);
            GameObject go = tilePrefab != null
                ? Instantiate(tilePrefab, pos, Quaternion.identity, transform)
                : CreateDefaultTile(pos);

            go.name = $"Tile_{x}_{z}";
            Tile tile = go.GetComponent<Tile>() ?? go.AddComponent<Tile>();

            tile.colorNormal   = colorNormal;
            tile.colorSelected = colorSelected;
            tile.colorMoveable = colorMoveable;
            tile.colorPath     = colorPath;
            tile.Init(x, z);

            tiles[x, z] = tile;
        }
    }

    GameObject CreateDefaultTile(Vector3 pos)
    {
        GameObject go = GameObject.CreatePrimitive(PrimitiveType.Cube);
        go.transform.parent   = transform;
        go.transform.position = pos;
        go.transform.localScale = new Vector3(tileSize - 0.05f, tileHeight, tileSize - 0.05f);

        // Collider 는 Tile 클릭 감지용으로 유지
        return go;
    }

    // ── 좌표 변환 ────────────────────────────────────────────────────
    public Vector3 GridToWorld(int x, int z)
        => new Vector3(x * tileSize, 0f, z * tileSize);

    public bool WorldToGrid(Vector3 worldPos, out int x, out int z)
    {
        x = Mathf.RoundToInt(worldPos.x / tileSize);
        z = Mathf.RoundToInt(worldPos.z / tileSize);
        return IsValidCoord(x, z);
    }

    // ── 타일 접근 ────────────────────────────────────────────────────
    public Tile GetTile(int x, int z)
        => IsValidCoord(x, z) ? tiles[x, z] : null;

    public bool IsValidCoord(int x, int z)
        => x >= 0 && x < width && z >= 0 && z < height;

    /// <summary>유닛이 이동 가능한 타일 목록을 BFS로 계산 (이동력 기반)</summary>
    public List<Tile> GetReachableTiles(int startX, int startZ, int moveRange)
    {
        var reachable = new List<Tile>();
        var visited   = new Dictionary<(int, int), int>(); // 좌표 -> 남은 이동력
        var queue     = new Queue<(int x, int z, int moves)>();

        visited[(startX, startZ)] = moveRange;
        queue.Enqueue((startX, startZ, moveRange));

        int[] dx = { 0, 0, 1, -1 };
        int[] dz = { 1, -1, 0, 0 };

        while (queue.Count > 0)
        {
            var (cx, cz, moves) = queue.Dequeue();
            if (cx != startX || cz != startZ)
                reachable.Add(tiles[cx, cz]);

            if (moves <= 0) continue;

            for (int i = 0; i < 4; i++)
            {
                int nx = cx + dx[i];
                int nz = cz + dz[i];
                if (!IsValidCoord(nx, nz)) continue;

                Tile next = tiles[nx, nz];
                if (next.IsOccupied) continue;           // 다른 유닛이 있으면 통과 불가

                int newMoves = moves - 1;
                if (!visited.ContainsKey((nx, nz)) || visited[(nx, nz)] < newMoves)
                {
                    visited[(nx, nz)] = newMoves;
                    queue.Enqueue((nx, nz, newMoves));
                }
            }
        }
        return reachable;
    }

    /// <summary>모든 타일 하이라이트 초기화</summary>
    public void ClearHighlights()
    {
        for (int x = 0; x < width; x++)
        for (int z = 0; z < height; z++)
            tiles[x, z].SetState(Tile.HighlightState.Normal);
    }

    /// <summary>마우스 클릭 레이캐스트로 타일 찾기</summary>
    public Tile GetTileUnderMouse()
    {
        Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition);
        if (Physics.Raycast(ray, out RaycastHit hit, 200f))
            return hit.collider.GetComponentInParent<Tile>();
        return null;
    }
}

