using UnityEngine;

/// <summary>
/// 게임 기물(유닛) 기본 클래스
/// </summary>
public class Unit : MonoBehaviour
{
    [Header("Unit Info")]
    public string unitName = "Unit";
    public Sprite  unitIcon;          // UI 아이콘 (선택 사항)

    [Header("Stats")]
    public int maxHp       = 100;
    public int maxMoveRange = 3;      // 턴당 최대 이동 칸 수

    // ── 런타임 상태 ──────────────────────────────────────────────────
    public int  CurrentHp        { get; private set; }
    public int  MovesLeft        { get; private set; }
    public bool HasActed         { get; private set; }  // 행동(공격 등) 완료 여부
    public int  GridX            { get; private set; }
    public int  GridZ            { get; private set; }

    public bool CanMove  => MovesLeft > 0 && !HasActed;
    public bool IsExhausted => MovesLeft == 0 || HasActed;

    // ── 이벤트 ───────────────────────────────────────────────────────
    public event System.Action<Unit> OnStatsChanged;

    // ── HP 바 (선택 사항) ─────────────────────────────────────────────
    [Header("World UI")]
    public GameObject hpBarPrefab;    // 프리팹 있으면 자동 생성

    void Awake()
    {
        CurrentHp = maxHp;
        MovesLeft = maxMoveRange;
    }

    // ── 초기 배치 ────────────────────────────────────────────────────
    public void PlaceOnTile(Tile tile)
    {
        // 이전 타일 비우기
        if (GridManager.Instance != null)
        {
            Tile old = GridManager.Instance.GetTile(GridX, GridZ);
            if (old != null && old.OccupiedUnit == this)
                old.OccupiedUnit = null;
        }

        GridX = tile.x;
        GridZ = tile.z;
        tile.OccupiedUnit = this;
        transform.position = tile.WorldCenter + Vector3.up * 0.5f;
    }

    // ── 이동 ─────────────────────────────────────────────────────────
    /// <summary>타일로 이동. 이동력 소비. 거리는 맨해튼 거리로 계산.</summary>
    public void MoveTo(Tile targetTile)
    {
        int dist = Mathf.Abs(targetTile.x - GridX) + Mathf.Abs(targetTile.z - GridZ);
        MovesLeft = Mathf.Max(0, MovesLeft - dist);

        PlaceOnTile(targetTile);
        OnStatsChanged?.Invoke(this);

        RefreshExhaustedVisual();
    }

    // ── 턴 초기화 ────────────────────────────────────────────────────
    public void OnTurnStart()
    {
        MovesLeft = maxMoveRange;
        HasActed  = false;
        RefreshExhaustedVisual();
        OnStatsChanged?.Invoke(this);
    }

    // ── 피해 ─────────────────────────────────────────────────────────
    public void TakeDamage(int amount)
    {
        CurrentHp = Mathf.Max(0, CurrentHp - amount);
        OnStatsChanged?.Invoke(this);
        if (CurrentHp <= 0) Die();
    }

    void Die()
    {
        Tile t = GridManager.Instance?.GetTile(GridX, GridZ);
        if (t != null && t.OccupiedUnit == this) t.OccupiedUnit = null;
        UnitManager.Instance?.UnregisterUnit(this);
        Destroy(gameObject);
    }

    // ── 시각적 피드백 ─────────────────────────────────────────────────
    void RefreshExhaustedVisual()
    {
        // 이동 불가 유닛은 어둡게 표시
        var renderers = GetComponentsInChildren<Renderer>();
        foreach (var r in renderers)
        {
            Color c = IsExhausted
                ? Color.Lerp(r.material.color, Color.gray, 0.5f)
                : Color.white;
            // 단순히 색 변경 (실제 게임에서는 shader property 사용 권장)
        }
    }

    /// <summary>Inspector 에서 확인용 HP 비율</summary>
    public float HpRatio => (float)CurrentHp / maxHp;
}

