    public static UnitManager Instance { get; private set; }

    // ── 선택 상태 ────────────────────────────────────────────────────
    public Unit SelectedUnit { get; private set; }
    private List<Tile> moveableTiles = new List<Tile>();

    // ── 등록된 유닛 목록 ─────────────────────────────────────────────
    private List<Unit> allUnits = new List<Unit>();

    // ── 이벤트 ───────────────────────────────────────────────────────
    public event System.Action<Unit> OnUnitSelected;
    public event System.Action       OnUnitDeselected;

    void Awake()
    {
        if (Instance != null && Instance != this) { Destroy(gameObject); return; }
        Instance = this;
    }

    void Update()
    {
        if (Input.GetMouseButtonDown(0))
            HandleLeftClick();
    }

    // ── 클릭 처리 ────────────────────────────────────────────────────
    void HandleLeftClick()
    {
        // UI 위 클릭이면 무시
        if (UnityEngine.EventSystems.EventSystem.current != null &&
            UnityEngine.EventSystems.EventSystem.current.IsPointerOverGameObject())
            return;

        Tile clickedTile = GridManager.Instance?.GetTileUnderMouse();
        if (clickedTile == null)
        {
            Deselect();
            return;
        }

        // 이동 가능 타일 클릭 → 이동
        if (SelectedUnit != null && moveableTiles.Contains(clickedTile))
        {
            MoveSelectedUnit(clickedTile);
            return;
        }

        // 유닛이 있는 타일 클릭 → 선택
        if (clickedTile.OccupiedUnit != null)
        {
            SelectUnit(clickedTile.OccupiedUnit);
            return;
        }

        // 빈 타일 클릭 → 선택 해제
        Deselect();
    }

    // ── 유닛 선택 ────────────────────────────────────────────────────
    void SelectUnit(Unit unit)
    {
        Deselect(); // 이전 선택 초기화

        SelectedUnit = unit;

        // 선택 타일 하이라이트
        Tile currentTile = GridManager.Instance.GetTile(unit.GridX, unit.GridZ);
        currentTile?.SetState(Tile.HighlightState.Selected);

        // 이동 가능 타일 표시
        if (unit.CanMove)
        {
            moveableTiles = GridManager.Instance.GetReachableTiles(unit.GridX, unit.GridZ, unit.MovesLeft);
            foreach (Tile t in moveableTiles)
                t.SetState(Tile.HighlightState.Moveable);
        }

        OnUnitSelected?.Invoke(unit);
    }

    // ── 이동 ─────────────────────────────────────────────────────────
    void MoveSelectedUnit(Tile target)
    {
        Unit unit = SelectedUnit;
        ClearMoveHighlights();
        unit.MoveTo(target);

        // 이동 후 다시 선택 상태로 (남은 이동력 있으면 이동 타일 재표시)
        SelectUnit(unit);
    }

    // ── 선택 해제 ────────────────────────────────────────────────────
    public void Deselect()
    {
        ClearMoveHighlights();
        GridManager.Instance?.ClearHighlights();
        SelectedUnit = null;
        moveableTiles.Clear();
        OnUnitDeselected?.Invoke();
    }

    void ClearMoveHighlights()
    {
        foreach (Tile t in moveableTiles)
            if (t.CurrentState == Tile.HighlightState.Moveable || t.CurrentState == Tile.HighlightState.Path)
                t.SetState(Tile.HighlightState.Normal);
    }

    // ── 유닛 등록/해제 ───────────────────────────────────────────────
    public void RegisterUnit(Unit unit)
    {
        if (!allUnits.Contains(unit)) allUnits.Add(unit);
    }

    public void UnregisterUnit(Unit unit)
    {
        allUnits.Remove(unit);
        if (SelectedUnit == unit) Deselect();
    }

    /// <summary>
    /// 새 유닛을 특정 타일에 스폰
    /// </summary>
    public Unit SpawnUnit(GameObject prefab, int gridX, int gridZ)
    {
        Tile tile = GridManager.Instance?.GetTile(gridX, gridZ);
        if (tile == null || tile.IsOccupied)
        {
            Debug.LogWarning($"[UnitManager] 타일 ({gridX},{gridZ}) 에 스폰 불가");
            return null;
        }
        GameObject go   = Instantiate(prefab, tile.WorldCenter + Vector3.up * 0.5f, Quaternion.identity);
        Unit       unit = go.GetComponent<Unit>();
        if (unit == null) unit = go.AddComponent<Unit>();
        unit.PlaceOnTile(tile);
        RegisterUnit(unit);
        return unit;
    }

    /// <summary>턴 시작 시 모든 유닛 이동력 회복</summary>
    public void OnTurnStart()
    {
        Deselect();
        foreach (Unit u in allUnits) u.OnTurnStart();
    }

    public List<Unit> GetAllUnits() => new List<Unit>(allUnits);
}

