using UnityEngine;
using UnityEngine.Events;

/// <summary>
/// 턴 관리자
/// - 현재 턴 번호 추적
/// - 턴 종료 시 모든 유닛 이동력 회복
/// - GameUI 에서 EndTurn() 버튼에 연결
/// </summary>
public class TurnManager : MonoBehaviour
{
    public static TurnManager Instance { get; private set; }

    public int CurrentTurn { get; private set; } = 1;

    // ── 이벤트 ───────────────────────────────────────────────────────
    public UnityEvent<int> OnTurnChanged;   // 새 턴 번호 전달

    void Awake()
    {
        if (Instance != null && Instance != this) { Destroy(gameObject); return; }
        Instance = this;

        if (OnTurnChanged == null)
            OnTurnChanged = new UnityEvent<int>();
    }

    void Start()
    {
        // 첫 턴 시작
        StartTurn();
    }

    // ── 턴 종료 (UI 버튼에서 호출) ───────────────────────────────────
    public void EndTurn()
    {
        CurrentTurn++;
        StartTurn();
    }

    void StartTurn()
    {
        Debug.Log($"[TurnManager] 턴 {CurrentTurn} 시작");

        // 유닛 이동력 회복
        UnitManager.Instance?.OnTurnStart();

        // UI 갱신
        OnTurnChanged?.Invoke(CurrentTurn);
    }
}

