        var hpText  = MakeTMPText(unitPanel.transform, "HpText",   "HP: 100/100", 16,
            new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0f, -70f), new Vector2(0f, -35f));
        var moveText = MakeTMPText(unitPanel.transform, "MoveText", "이동력: 3/3", 16,
            new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0f, -100f), new Vector2(0f, -65f));

        // HP Bar (Slider)
        GameObject sliderGo = new GameObject("HpBar");
        sliderGo.transform.SetParent(unitPanel.transform, false);
        var sliderRect = sliderGo.AddComponent<RectTransform>();
        sliderRect.anchorMin = new Vector2(0.05f, 0f);
        sliderRect.anchorMax = new Vector2(0.95f, 0f);
        sliderRect.offsetMin = new Vector2(0f, 10f);
        sliderRect.offsetMax = new Vector2(0f, 30f);
        var slider = sliderGo.AddComponent<Slider>();
        slider.value = 1f;

        // Turn Panel (우하단)
        GameObject turnPanel = MakePanel(canvasGo.transform, "TurnPanel",
            new Vector2(1f, 0f), new Vector2(1f, 0f),
            new Vector2(1f, 0f), new Vector2(1f, 0f),
            new Vector2(220f, 110f));
        turnPanel.GetComponent<Image>().color = new Color(0.1f, 0.1f, 0.15f, 0.85f);
        var turnRect = turnPanel.GetComponent<RectTransform>();
        turnRect.pivot   = new Vector2(1f, 0f);
        turnRect.anchoredPosition = new Vector2(-20f, 20f);

        var turnText = MakeTMPText(turnPanel.transform, "TurnText", "Turn 1", 22,
            new Vector2(0f, 0.5f), new Vector2(1f, 1f), Vector2.zero, Vector2.zero);

        // End Turn Button
        GameObject btnGo = new GameObject("EndTurnButton");
        btnGo.transform.SetParent(turnPanel.transform, false);
        var btnRect = btnGo.AddComponent<RectTransform>();
        btnRect.anchorMin = new Vector2(0.1f, 0f);
        btnRect.anchorMax = new Vector2(0.9f, 0.45f);
        btnRect.offsetMin = btnRect.offsetMax = Vector2.zero;
        var btnImg = btnGo.AddComponent<Image>();
        btnImg.color = new Color(0.2f, 0.6f, 0.3f);
        var btn = btnGo.AddComponent<Button>();
        GameObject btnTextGo = new GameObject("Text");
        btnTextGo.transform.SetParent(btnGo.transform, false);
        var btnTmp = btnTextGo.AddComponent<TextMeshProUGUI>();
        btnTmp.text = "턴 종료";
        btnTmp.fontSize = 18;
        btnTmp.alignment = TextAlignmentOptions.Center;
        btnTmp.color = Color.white;
        var btnTextRect = btnTextGo.GetComponent<RectTransform>();
        btnTextRect.anchorMin = Vector2.zero;
        btnTextRect.anchorMax = Vector2.one;
        btnTextRect.offsetMin = btnTextRect.offsetMax = Vector2.zero;

        // ── 5. GameUI 연결 ────────────────────────────────────────────
        var gameUI = gm.AddComponent<GameUI>();
        gameUI.unitPanel   = unitPanel;
        gameUI.unitNameText = unitNameText;
        gameUI.hpText      = hpText;
        gameUI.moveText    = moveText;
        gameUI.hpBar       = slider;
        gameUI.turnText    = turnText;
        gameUI.endTurnButton = btn;

        Debug.Log("[DAS3D] 씬 세팅 완료! Play 버튼을 눌러 테스트하세요.");
        EditorUtility.DisplayDialog("DAS3D Setup", "씬 세팅 완료!\n\n" +
            "• GameManager 에서 GridManager > width/height 조정\n" +
            "• Unit 프리팹을 만들어 UnitManager.SpawnUnit() 으로 배치\n" +
            "• CameraRig > GameCamera 에서 맵 경계(minBounds/maxBounds) 조정", "OK");
    }

    // ── 헬퍼 ─────────────────────────────────────────────────────────
    static GameObject MakePanel(Transform parent, string name,
        Vector2 anchorMin, Vector2 anchorMax,
        Vector2 pivotMin,  Vector2 pivotMax,
        Vector2 size)
    {
        GameObject go = new GameObject(name);
        go.transform.SetParent(parent, false);
        var img  = go.AddComponent<Image>();
        var rect = go.GetComponent<RectTransform>();
        rect.anchorMin = anchorMin;
        rect.anchorMax = anchorMax;
        rect.sizeDelta = size;
        return go;
    }

    static TMP_Text MakeTMPText(Transform parent, string name, string text, int fontSize,
        Vector2 anchorMin, Vector2 anchorMax, Vector2 offsetMin, Vector2 offsetMax)
    {
        GameObject go = new GameObject(name);
        go.transform.SetParent(parent, false);
        var tmp  = go.AddComponent<TextMeshProUGUI>();
        tmp.text     = text;
        tmp.fontSize = fontSize;
        tmp.color    = Color.white;
        tmp.alignment = TextAlignmentOptions.Center;
        var rect = go.GetComponent<RectTransform>();
        rect.anchorMin = anchorMin;
        rect.anchorMax = anchorMax;
        rect.offsetMin = offsetMin;
        rect.offsetMax = offsetMax;
        return tmp;
    }
}
