using UnityEngine;

/// <summary>
/// 테스트용 유닛 스포너
/// GameManager 오브젝트에 붙이거나 별도 오브젝트에 붙여 사용
/// </summary>
public class UnitSpawner : MonoBehaviour
{
    [System.Serializable]
    public struct SpawnEntry
    {
        public string unitName;
        public int    gridX;
        public int    gridZ;
        public int    maxHp;
        public int    moveRange;
        public Color  color;
    }

    [Header("Spawn on Start")]
    public SpawnEntry[] spawnList;

    void Start()
    {
        foreach (var entry in spawnList)
            SpawnDefault(entry);
    }

    void SpawnDefault(SpawnEntry entry)
    {
        Tile tile = GridManager.Instance?.GetTile(entry.gridX, entry.gridZ);
        if (tile == null || tile.IsOccupied)
        {
            Debug.LogWarning($"[UnitSpawner] ({entry.gridX},{entry.gridZ}) 스폰 불가");
            return;
        }

        // 기본 캡슐 모양 유닛 생성
        GameObject go = GameObject.CreatePrimitive(PrimitiveType.Capsule);
        go.name = entry.unitName;
        go.GetComponent<Renderer>().material.color = entry.color;

        // 콜라이더를 MeshCollider 가 아닌 CapsuleCollider 유지 (이미 있음)

        Unit unit = go.AddComponent<Unit>();
        unit.unitName     = entry.unitName;
        unit.maxHp        = entry.maxHp > 0 ? entry.maxHp : 100;
        unit.maxMoveRange = entry.moveRange > 0 ? entry.moveRange : 3;

        unit.PlaceOnTile(tile);
        UnitManager.Instance?.RegisterUnit(unit);
    }
}

