/// <summary>
/// 게임 기물(유닛) 기본 클래스
/// </summary>
public class Unit : MonoBehaviour
{
    [Header("Unit Info")]
    public string unitName = "Unit";
    public Sprite  unitIcon;

    [Header("Stats")]
    public int maxHp        = 100;
    public int maxMoveRange = 3;

    [Header("Outline")]
    [Range(1.02f, 1.15f)]
    public float outlineScale = 1.06f;

    // ── 런타임 상태 ──────────────────────────────────────────────────
    public int  CurrentHp   { get; private set; }
    public int  MovesLeft   { get; private set; }
    public bool HasActed    { get; private set; }
    public int  GridX       { get; private set; }
    public int  GridZ       { get; private set; }

    public bool CanMove     => MovesLeft > 0 && !HasActed;
    public bool IsExhausted => MovesLeft == 0 || HasActed;
    public float HpRatio    => (float)CurrentHp / maxHp;

    public event System.Action<Unit> OnStatsChanged;

    // ── 아웃라인 ─────────────────────────────────────────────────────
    private GameObject outlineGo;
    private Material   outlineMat;

    // ── 초기화 ───────────────────────────────────────────────────────
    void Awake()
    {
        CurrentHp = maxHp;
        MovesLeft = maxMoveRange;
    }

    void Start()
    {
        BuildOutline();
    }

    void BuildOutline()
    {
        MeshFilter sourceMF = GetComponentInChildren<MeshFilter>();
        if (sourceMF == null) return;

        Shader outlineShader = Shader.Find("DAS3D/Outline");
        if (outlineShader == null)
        {
            Debug.LogWarning("[Unit] DAS3D/Outline 셰이더를 찾을 수 없습니다. Outline.shader 가 Assets/Shaders/ 에 있는지 확인하세요.");
            return;
        }

        // 유닛 기본색의 보색 계산 (HSV 색상 +180°)
        Renderer baseRenderer = GetComponentInChildren<Renderer>();
        Color baseColor = baseRenderer != null ? baseRenderer.material.color : Color.white;

        Color.RGBToHSV(baseColor, out float h, out float s, out float v);
        h = (h + 0.5f) % 1f;
        Color complementary = Color.HSVToRGB(h, Mathf.Max(s, 0.6f), Mathf.Max(v, 0.7f));

        // 아웃라인 머티리얼 생성
        outlineMat = new Material(outlineShader);
        outlineMat.SetColor("_OutlineColor", complementary);

        // 아웃라인 GO 생성 (유닛과 동일 메시, 살짝 확대)
        outlineGo = new GameObject("_Outline");
        outlineGo.transform.SetParent(transform);
        outlineGo.transform.SetLocalPositionAndRotation(Vector3.zero, Quaternion.identity);
        outlineGo.transform.localScale = Vector3.one * outlineScale;

        MeshFilter mf = outlineGo.AddComponent<MeshFilter>();
        mf.mesh = sourceMF.sharedMesh;

        MeshRenderer mr = outlineGo.AddComponent<MeshRenderer>();
        mr.material = outlineMat;
        mr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
        mr.receiveShadows = false;

        outlineGo.SetActive(false);
    }

    /// <summary>UnitManager 가 호버 감지 후 호출</summary>
    public void SetHoverOutline(bool show)
    {
        if (outlineGo != null) outlineGo.SetActive(show);
    }

    // ── 배치 ─────────────────────────────────────────────────────────
    public void PlaceOnTile(Tile tile)
    {
        Tile old = GridManager.Instance?.GetTile(GridX, GridZ);
        if (old != null && old.OccupiedUnit == this) old.OccupiedUnit = null;

        GridX = tile.x;
        GridZ = tile.z;
        tile.OccupiedUnit = this;
        transform.position = tile.WorldCenter + Vector3.up * 0.5f;
    }

    // ── 이동 ─────────────────────────────────────────────────────────
    public void MoveTo(Tile targetTile)
    {
        int dist = Mathf.Abs(targetTile.x - GridX) + Mathf.Abs(targetTile.z - GridZ);
        MovesLeft = Mathf.Max(0, MovesLeft - dist);
        PlaceOnTile(targetTile);
        OnStatsChanged?.Invoke(this);
    }

    // ── 턴 초기화 ────────────────────────────────────────────────────
    public void OnTurnStart()
    {
        MovesLeft = maxMoveRange;
        HasActed  = false;
        OnStatsChanged?.Invoke(this);
    }

    // ── 피해 ─────────────────────────────────────────────────────────
    public void TakeDamage(int amount)
    {
        CurrentHp = Mathf.Max(0, CurrentHp - amount);
        OnStatsChanged?.Invoke(this);
        if (CurrentHp <= 0) Die();
    }

    void Die()
    {
        Tile t = GridManager.Instance?.GetTile(GridX, GridZ);
        if (t != null && t.OccupiedUnit == this) t.OccupiedUnit = null;
        UnitManager.Instance?.UnregisterUnit(this);
        Destroy(gameObject);
    }
}

