     1→using System.Collections.Generic;
     2→using UnityEngine;
     3→
     4→/// <summary>
     5→/// 유닛 선택 · 이동 · 관리
     6→/// 좌클릭: 유닛 선택 / 이동 가능 타일 클릭 시 이동
     7→/// </summary>
     8→public class UnitManager : MonoBehaviour
     9→{
    10→    public static UnitManager Instance { get; private set; }
    11→
    12→    // ── 선택 상태 ────────────────────────────────────────────────────
    13→    public Unit SelectedUnit { get; private set; }
    14→    private List<Tile> moveableTiles = new List<Tile>();
    15→
    16→    // ── 등록된 유닛 목록 ─────────────────────────────────────────────
    17→    private List<Unit> allUnits = new List<Unit>();
    18→
    19→    // ── 이벤트 ───────────────────────────────────────────────────────
    20→    public event System.Action<Unit> OnUnitSelected;
    21→    public event System.Action       OnUnitDeselected;
    22→
    23→    void Awake()
    24→    {
    25→        if (Instance != null && Instance != this) { Destroy(gameObject); return; }
    26→        Instance = this;
    27→    }
    28→
    29→    void Update()
    30→    {
    31→        if (Input.GetMouseButtonDown(0))
    32→            HandleLeftClick();
    33→    }
    34→
    35→    // ── 클릭 처리 ────────────────────────────────────────────────────
    36→    void HandleLeftClick()
    37→    {
    38→        // UI 위 클릭이면 무시
    39→        if (UnityEngine.EventSystems.EventSystem.current != null &&
    40→            UnityEngine.EventSystems.EventSystem.current.IsPointerOverGameObject())
    41→            return;
    42→
    43→        Tile clickedTile = GridManager.Instance?.GetTileUnderMouse();
    44→        if (clickedTile == null)
    45→        {
    46→            Deselect();
    47→            return;
    48→        }
    49→
    50→        // 이동 가능 타일 클릭 → 이동
    51→        if (SelectedUnit != null && moveableTiles.Contains(clickedTile))
    52→        {
    53→            MoveSelectedUnit(clickedTile);
    54→            return;
    55→        }
    56→
    57→        // 유닛이 있는 타일 클릭 → 선택
    58→        if (clickedTile.OccupiedUnit != null)
    59→        {
    60→            SelectUnit(clickedTile.OccupiedUnit);
    61→            return;
    62→        }
    63→
    64→        // 빈 타일 클릭 → 선택 해제
    65→        Deselect();
    66→    }
    67→
    68→    // ── 유닛 선택 ────────────────────────────────────────────────────
    69→    void SelectUnit(Unit unit)
    70→    {
    71→        Deselect(); // 이전 선택 초기화
    72→
    73→        SelectedUnit = unit;
    74→
    75→        // 선택 타일 하이라이트
    76→        Tile currentTile = GridManager.Instance.GetTile(unit.GridX, unit.GridZ);
    77→        currentTile?.SetState(Tile.HighlightState.Selected);
    78→
    79→        // 이동 가능 타일 표시
    80→        if (unit.CanMove)
    81→        {
    82→            moveableTiles = GridManager.Instance.GetReachableTiles(unit.GridX, unit.GridZ, unit.MovesLeft);
    83→            foreach (Tile t in moveableTiles)
    84→                t.SetState(Tile.HighlightState.Moveable);
    85→        }
    86→
    87→        OnUnitSelected?.Invoke(unit);
    88→    }
    89→
    90→    // ── 이동 ─────────────────────────────────────────────────────────
    91→    void MoveSelectedUnit(Tile target)
    92→    {
    93→        Unit unit = SelectedUnit;
    94→        ClearMoveHighlights();
    95→        unit.MoveTo(target);
    96→
    97→        // 이동 후 다시 선택 상태로 (남은 이동력 있으면 이동 타일 재표시)
    98→        SelectUnit(unit);
    99→    }
   100→
   101→    // ── 선택 해제 ────────────────────────────────────────────────────
   102→    public void Deselect()
   103→    {
   104→        ClearMoveHighlights();
   105→        GridManager.Instance?.ClearHighlights();
   106→        SelectedUnit = null;
   107→        moveableTiles.Clear();
   108→        OnUnitDeselected?.Invoke();
   109→    }
   110→
   111→    void ClearMoveHighlights()
   112→    {
   113→        foreach (Tile t in moveableTiles)
   114→            if (t.CurrentState == Tile.HighlightState.Moveable || t.CurrentState == Tile.HighlightState.Path)
   115→                t.SetState(Tile.HighlightState.Normal);
   116→    }
   117→
   118→    // ── 유닛 등록/해제 ───────────────────────────────────────────────
   119→    public void RegisterUnit(Unit unit)
   120→    {
   121→        if (!allUnits.Contains(unit)) allUnits.Add(unit);
   122→    }
   123→
   124→    public void UnregisterUnit(Unit unit)
   125→    {
   126→        allUnits.Remove(unit);
   127→        if (SelectedUnit == unit) Deselect();
   128→    }
   129→
   130→    /// <summary>
   131→    /// 새 유닛을 특정 타일에 스폰
   132→    /// </summary>
   133→    public Unit SpawnUnit(GameObject prefab, int gridX, int gridZ)
   134→    {
   135→        Tile tile = GridManager.Instance?.GetTile(gridX, gridZ);
   136→        if (tile == null || tile.IsOccupied)
   137→        {
   138→            Debug.LogWarning($"[UnitManager] 타일 ({gridX},{gridZ}) 에 스폰 불가");
   139→            return null;
   140→        }
   141→        GameObject go   = Instantiate(prefab, tile.WorldCenter + Vector3.up * 0.5f, Quaternion.identity);
   142→        Unit       unit = go.GetComponent<Unit>();
   143→        if (unit == null) unit = go.AddComponent<Unit>();
   144→        unit.PlaceOnTile(tile);
   145→        RegisterUnit(unit);
   146→        return unit;
   147→    }
   148→
   149→    /// <summary>턴 시작 시 모든 유닛 이동력 회복</summary>
   150→    public void OnTurnStart()
   151→    {
   152→        Deselect();
   153→        foreach (Unit u in allUnits) u.OnTurnStart();
   154→    }
