    void OnLocationChanging(GameLocation nextLocation)
    {
        if (transitionPanel == null) return;
        StopAllCoroutines();
        StartCoroutine(ShowTransition(nextLocation));
    }

    IEnumerator ShowTransition(GameLocation nextLocation)
    {
        // 텍스트 설정
        bool goingToRaphdonia = nextLocation == GameLocation.Raphdonia;

        if (transitionTitle != null)
            transitionTitle.text = goingToRaphdonia ? "라프도니아로 복귀" : "전투 시작";

        if (transitionSub != null)
            transitionSub.text = goingToRaphdonia
                ? "전투 턴이 모두 소진되었습니다."
                : "라프도니아 턴이 모두 소진되었습니다.";

        transitionPanel.SetActive(true);
        endTurnButton?.gameObject.SetActive(false);   // 전환 중 버튼 비활성

        yield return new WaitForSeconds(transitionDuration);

        transitionPanel.SetActive(false);
        endTurnButton?.gameObject.SetActive(true);
    }
}

