            if (mp.x < edgeScrollThreshold)                   input -= Vector3.right;
            if (mp.x > Screen.width  - edgeScrollThreshold)   input += Vector3.right;
            if (mp.y < edgeScrollThreshold)                    input -= Vector3.forward;
            if (mp.y > Screen.height - edgeScrollThreshold)   input += Vector3.forward;
        }

        // 중간 버튼 드래그 패닝
        if (Input.GetMouseButtonDown(2)) lastMousePos = Input.mousePosition;
        if (Input.GetMouseButton(2))
        {
            Vector3 delta = Input.mousePosition - lastMousePos;
            Vector3 flatRight   = FlatDir(transform.right);
            Vector3 flatForward = FlatDir(transform.forward);
            input -= flatRight   * delta.x * 0.04f;
            input -= flatForward * delta.y * 0.04f;
            lastMousePos = Input.mousePosition;
        }

        if (input.sqrMagnitude > 0.01f)
        {
            float zoomRatio = Mathf.InverseLerp(minZoom, maxZoom, currentZoom);
            float speed = panSpeed * Mathf.Lerp(0.5f, 2f, zoomRatio);
            Vector3 move = TransformInput(input) * speed * Time.deltaTime;
            moveVelocity = Vector3.Lerp(moveVelocity, move, panAcceleration * Time.deltaTime);
        }
        else
        {
            moveVelocity = Vector3.Lerp(moveVelocity, Vector3.zero, panAcceleration * Time.deltaTime);
        }

        transform.position += moveVelocity;
    }

    Vector3 FlatDir(Vector3 v) { v.y = 0f; return v.normalized; }

    Vector3 TransformInput(Vector3 input)
    {
        Vector3 fwd   = FlatDir(transform.forward);
        Vector3 right = FlatDir(transform.right);
        return (right * input.x + fwd * input.z).normalized;
    }

    // ── Zoom ─────────────────────────────────────────────────────────
    void HandleZoom()
    {
        float scroll = Input.GetAxis("Mouse ScrollWheel");
        targetZoom -= scroll * zoomSpeed * 10f;
        targetZoom = Mathf.Clamp(targetZoom, minZoom, maxZoom);
        currentZoom = Mathf.Lerp(currentZoom, targetZoom, zoomLerpSpeed * Time.deltaTime);
        ApplyCameraTransform();
    }

    void ApplyCameraTransform()
    {
        if (cam == null) return;
        float rad  = pitchAngle * Mathf.Deg2Rad;
        float yOff = currentZoom * Mathf.Sin(rad);
        float zOff = currentZoom * Mathf.Cos(rad);
        cam.transform.localPosition = new Vector3(0f, yOff, -zOff);
        cam.transform.localRotation = Quaternion.Euler(pitchAngle, 0f, 0f);
    }

    // ── Rotation ─────────────────────────────────────────────────────
    void HandleRotation()
    {
        if (Input.GetKey(KeyCode.Q)) transform.Rotate(Vector3.up, -keyRotationSpeed * Time.deltaTime, Space.World);
        if (Input.GetKey(KeyCode.E)) transform.Rotate(Vector3.up,  keyRotationSpeed * Time.deltaTime, Space.World);
    }

    // ── Clamp ────────────────────────────────────────────────────────
    void ClampPosition()
    {
        Vector3 p = transform.position;
        p.x = Mathf.Clamp(p.x, minBounds.x, maxBounds.x);
        p.z = Mathf.Clamp(p.z, minBounds.y, maxBounds.y);
        p.y = 0f;
        transform.position = p;
    }

    public void FocusOn(Vector3 worldPos) { worldPos.y = 0f; transform.position = worldPos; }
}

