using UnityEngine;

/// <summary>
/// 게임 시간/장소 관리자
///
/// ■ 라프도니아
///   - 1일씩 수동 진행 ("다음 날" 버튼)
///   - dungeonCycleDays(기본 30)마다 미궁 개방
///   - UI: "D-{n}" 표시, 0일 때 "D-0 미궁 개방!"
///
/// ■ 미궁
///   - 층별 체류 시간 제한 (floorTimeLimitsHours, 기본 168h = 24×7)
///   - 캐릭터 행동(이동·전투·상호작용)이 시간을 소비
///   - 시간 소진 → 자동 라프도니아 복귀
///   - "대기 (1h)" 버튼으로 수동 시간 소비 가능
/// </summary>
public class TurnManager : MonoBehaviour
{
    public static TurnManager Instance { get; private set; }

    // ── 라프도니아 설정 ────────────────────────────────────────────────
    [Header("라프도니아")]
    [Tooltip("미궁이 열리는 주기 (일)")]
    public int dungeonCycleDays = 30;

    // ── 미궁 설정 ─────────────────────────────────────────────────────
    [Header("미궁 층별 체류 시간 (시간 단위)")]
    [Tooltip("floorTimeLimitsHours[0] = 1층, [1] = 2층, ...")]
    public float[] floorTimeLimitsHours = { 168f, 240f, 336f };

    // ── 런타임 상태 ──────────────────────────────────────────────────
    public GameLocation CurrentLocation { get; private set; } = GameLocation.Raphdonia;

    // 라프도니아
    public int CurrentDay     { get; private set; } = 1;
    public int DaysUntilDungeon => dungeonCycleDays - ((CurrentDay - 1) % dungeonCycleDays) - 1;
    public bool IsDungeonOpen   => DaysUntilDungeon == 0;

    // 미궁
    public int   CurrentFloor        { get; private set; } = 1;
    public float TimeRemainingHours  { get; private set; }
    public float TimeLimitHours      => floorTimeLimitsHours[
                                            Mathf.Clamp(CurrentFloor - 1, 0, floorTimeLimitsHours.Length - 1)];

    // ── 이벤트 ───────────────────────────────────────────────────────
    /// <summary>라프도니아 상태 변경 (현재 날짜, 미궁까지 남은 일수)</summary>
    public event System.Action<int, int>       OnRaphdoniaUpdated;

    /// <summary>미궁 상태 변경 (남은 시간h, 제한 시간h, 현재 층)</summary>
    public event System.Action<float, float, int> OnDungeonUpdated;

    /// <summary>장소 전환 직전 발생 (전환 연출용)</summary>
    public event System.Action<GameLocation>   OnLocationChanging;

    // 시간 만료 처리를 다음 프레임에 수행 (MoveTo 내부에서 호출될 수 있으므로)
    private bool returnPending = false;

    // ── Unity ────────────────────────────────────────────────────────
    void Awake()
    {
        if (Instance != null && Instance != this) { Destroy(gameObject); return; }
        Instance = this;
    }

    void Start()
    {
        // 라프도니아에서 시작
        if (UnitManager.Instance != null) UnitManager.Instance.OnTurnStart();
        OnRaphdoniaUpdated?.Invoke(CurrentDay, DaysUntilDungeon);
    }

    void Update()
    {
        if (returnPending)
        {
            returnPending = false;
            ExitDungeon();
        }
    }

    // ══════════════════════════════════════════════════════════════════
    // 라프도니아 액션
    // ══════════════════════════════════════════════════════════════════

    /// <summary>하루 경과 (버튼에서 호출)</summary>
    public void AdvanceDay()
    {
        if (CurrentLocation != GameLocation.Raphdonia) return;
        CurrentDay++;
        if (UnitManager.Instance != null) UnitManager.Instance.OnTurnStart();
        OnRaphdoniaUpdated?.Invoke(CurrentDay, DaysUntilDungeon);
    }

    /// <summary>미궁 입장 (버튼에서 호출, IsDungeonOpen 일 때만 동작)</summary>
    public void EnterDungeon()
    {
        if (CurrentLocation != GameLocation.Raphdonia || !IsDungeonOpen) return;

        OnLocationChanging?.Invoke(GameLocation.Dungeon);
        CurrentLocation      = GameLocation.Dungeon;
        CurrentFloor         = 1;
        TimeRemainingHours   = TimeLimitHours;

        if (UnitManager.Instance != null) UnitManager.Instance.OnTurnStart();
        OnDungeonUpdated?.Invoke(TimeRemainingHours, TimeLimitHours, CurrentFloor);
    }

    // ══════════════════════════════════════════════════════════════════
    // 미궁 액션
    // ══════════════════════════════════════════════════════════════════

    /// <summary>
    /// 미궁에서 행동 시간 소비 – Unit.MoveTo, 전투, 상호작용 등에서 호출
    /// </summary>
    public void ConsumeTime(float hours)
    {
        if (CurrentLocation != GameLocation.Dungeon) return;

        TimeRemainingHours = Mathf.Max(0f, TimeRemainingHours - hours);
        OnDungeonUpdated?.Invoke(TimeRemainingHours, TimeLimitHours, CurrentFloor);

        if (TimeRemainingHours <= 0f)
            returnPending = true;
    }

    /// <summary>대기 1시간 (버튼에서 호출) – 유닛 이동력도 회복</summary>
    public void WaitOneHour()
    {
        if (CurrentLocation != GameLocation.Dungeon) return;
        if (UnitManager.Instance != null) UnitManager.Instance.OnTurnStart();
        ConsumeTime(1f);
    }

    // ══════════════════════════════════════════════════════════════════
    // 내부: 라프도니아 복귀
    // ══════════════════════════════════════════════════════════════════
    void ExitDungeon()
    {
        OnLocationChanging?.Invoke(GameLocation.Raphdonia);
        CurrentLocation = GameLocation.Raphdonia;
        CurrentDay++;   // 미궁 탐험이 하루 소비

        if (UnitManager.Instance != null) UnitManager.Instance.OnTurnStart();
        OnRaphdoniaUpdated?.Invoke(CurrentDay, DaysUntilDungeon);
    }

    // ── 공개 헬퍼 ────────────────────────────────────────────────────
    public string LocationDisplayName() =>
        CurrentLocation == GameLocation.Raphdonia ? "라프도니아" : $"미궁 {CurrentFloor}층";

    /// <summary>시간을 "167h 30m" 형식 문자열로 변환</summary>
    public static string FormatHours(float hours)
    {
        int h = Mathf.FloorToInt(hours);
        int m = Mathf.FloorToInt((hours - h) * 60f);
        return $"{h}h {m:D2}m";
    }
}

// ── 장소 열거형 ──────────────────────────────────────────────────────
public enum GameLocation { Raphdonia, Dungeon }

