using UnityEngine;

/// <summary>
/// 장소(Location) 와 턴 제한을 관리하는 매니저
///
/// 흐름:
///   라프도니아 (raphdoniaMaxTurns 턴) → 전투 (battleMaxTurns 턴) → 라프도니아 → ...
///
/// GameUI.endTurnButton → EndTurn() 연결
/// </summary>
public class TurnManager : MonoBehaviour
{
    public static TurnManager Instance { get; private set; }

    // ── 설정 ─────────────────────────────────────────────────────────
    [Header("라프도니아 턴 제한")]
    public int raphdoniaMaxTurns = 5;

    [Header("전투 턴 제한")]
    public int battleMaxTurns = 10;

    // ── 런타임 상태 ──────────────────────────────────────────────────
    public GameLocation CurrentLocation { get; private set; } = GameLocation.Raphdonia;
    public int          TurnInPhase     { get; private set; } = 1;   // 현재 장소 내 턴 번호
    public int          MaxTurns        { get; private set; }         // 현재 장소 최대 턴
    public int          TurnsLeft       { get; private set; }         // 남은 턴

    // ── 이벤트 ───────────────────────────────────────────────────────
    /// <summary>(turnInPhase, maxTurns, location)</summary>
    public event System.Action<int, int, GameLocation> OnTurnChanged;

    /// <summary>장소 전환 직전 발생 – GameUI 전환 화면에 사용</summary>
    public event System.Action<GameLocation>           OnLocationChanging;

    // ── Unity ────────────────────────────────────────────────────────
    void Awake()
    {
        if (Instance != null && Instance != this) { Destroy(gameObject); return; }
        Instance = this;
    }

    void Start()
    {
        EnterLocation(GameLocation.Raphdonia);
    }

    // ── 턴 종료 (버튼에서 호출) ──────────────────────────────────────
    public void EndTurn()
    {
        TurnInPhase++;
        TurnsLeft--;

        if (UnitManager.Instance != null) UnitManager.Instance.OnTurnStart();

        if (TurnsLeft <= 0)
        {
            // 장소 전환
            GameLocation next = CurrentLocation == GameLocation.Raphdonia
                ? GameLocation.Battle
                : GameLocation.Raphdonia;

            OnLocationChanging?.Invoke(next);   // GameUI 가 전환 패널 표시
            EnterLocation(next);
        }
        else
        {
            OnTurnChanged?.Invoke(TurnInPhase, MaxTurns, CurrentLocation);
        }
    }

    // ── 내부: 장소 진입 ──────────────────────────────────────────────
    void EnterLocation(GameLocation location)
    {
        CurrentLocation = location;
        TurnInPhase     = 1;
        MaxTurns        = location == GameLocation.Raphdonia ? raphdoniaMaxTurns : battleMaxTurns;
        TurnsLeft       = MaxTurns;

        if (UnitManager.Instance != null) UnitManager.Instance.OnTurnStart();

        OnTurnChanged?.Invoke(TurnInPhase, MaxTurns, CurrentLocation);
    }

    // ── 공개 헬퍼 ────────────────────────────────────────────────────
    public string LocationDisplayName()
        => CurrentLocation == GameLocation.Raphdonia ? "라프도니아" : "전투";
}

// ── 장소 열거형 ──────────────────────────────────────────────────────
public enum GameLocation { Raphdonia, Battle }

