using System.Collections;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// 게임 전체 UI 관리
///
/// [TurnPanel 버튼 동작]
///   라프도니아 + 미궁 닫힘 → "다음 날"  → AdvanceDay()
///   라프도니아 + 미궁 개방 → "미궁 입장" → EnterDungeon()
///   미궁                  → "대기 (1h)" → WaitOneHour()
/// </summary>
public class GameUI : MonoBehaviour
{
    [Header("Unit Panel")]
    public GameObject unitPanel;
    public TMP_Text   unitNameText;
    public TMP_Text   hpText;
    public TMP_Text   moveText;
    public Slider     hpBar;

    [Header("Turn Panel")]
    public TMP_Text locationText;
    public TMP_Text turnText;
    public Button   endTurnButton;

    [Header("Transition Overlay")]
    public GameObject transitionPanel;
    public TMP_Text   transitionTitle;
    public TMP_Text   transitionSub;
    [Tooltip("전환 패널이 표시되는 시간(초)")]
    public float transitionDuration = 2.5f;

    // ── 캐시 ─────────────────────────────────────────────────────────
    private Image    endTurnButtonImage;
    private TMP_Text endTurnButtonLabel;

    // 버튼 색상 프리셋
    static readonly Color ColorNormalDay    = new Color(0.20f, 0.50f, 0.80f);
    static readonly Color ColorDungeonOpen  = new Color(0.55f, 0.15f, 0.75f);
    static readonly Color ColorWait         = new Color(0.45f, 0.20f, 0.35f);
    static readonly Color ColorUrgent       = new Color(0.80f, 0.20f, 0.10f);

    // ── Unity ────────────────────────────────────────────────────────
    void Start()
    {
        // 유닛 이벤트
        UnitManager.Instance.OnUnitSelected   += ShowUnitPanel;
        UnitManager.Instance.OnUnitDeselected += HideUnitPanel;

        // 턴/시간 이벤트
        TurnManager.Instance.OnRaphdoniaUpdated  += OnRaphdoniaUpdated;
        TurnManager.Instance.OnDungeonUpdated    += OnDungeonUpdated;
        TurnManager.Instance.OnLocationChanging  += OnLocationChanging;

        // 버튼 캐시 및 리스너
        if (endTurnButton != null)
        {
            endTurnButton.onClick.AddListener(OnMainButtonClicked);
            endTurnButtonImage = endTurnButton.GetComponent<Image>();
            endTurnButtonLabel = endTurnButton.GetComponentInChildren<TMP_Text>();
        }

        HideUnitPanel();
        if (transitionPanel != null) transitionPanel.SetActive(false);

        // 초기 상태 표시
        OnRaphdoniaUpdated(TurnManager.Instance.CurrentDay,
                           TurnManager.Instance.DaysUntilDungeon);
    }

    void OnDestroy()
    {
        if (UnitManager.Instance != null)
        {
            UnitManager.Instance.OnUnitSelected   -= ShowUnitPanel;
            UnitManager.Instance.OnUnitDeselected -= HideUnitPanel;
        }
        if (TurnManager.Instance != null)
        {
            TurnManager.Instance.OnRaphdoniaUpdated -= OnRaphdoniaUpdated;
            TurnManager.Instance.OnDungeonUpdated   -= OnDungeonUpdated;
            TurnManager.Instance.OnLocationChanging -= OnLocationChanging;
        }
    }

    // ── 메인 버튼 ────────────────────────────────────────────────────
    /// <summary>EndTurnButton.onClick 에 연결된 통합 핸들러</summary>
    public void OnMainButtonClicked()
    {
        switch (TurnManager.Instance.CurrentLocation)
        {
            case GameLocation.Raphdonia:
                if (TurnManager.Instance.IsDungeonOpen)
                    TurnManager.Instance.EnterDungeon();
                else
                    TurnManager.Instance.AdvanceDay();
                break;
            case GameLocation.Dungeon:
                TurnManager.Instance.WaitOneHour();
                break;
        }
    }

    // ── 라프도니아 표시 ───────────────────────────────────────────────
    void OnRaphdoniaUpdated(int day, int daysUntilDungeon)
    {
        if (locationText != null) locationText.text = "라프도니아";

        if (turnText != null)
            turnText.text = daysUntilDungeon > 0
                ? $"D-{daysUntilDungeon}"
                : "D-0  미궁 개방!";

        bool dungeonOpen = daysUntilDungeon == 0;

        if (endTurnButtonLabel != null)
            endTurnButtonLabel.text = dungeonOpen ? "미궁 입장" : "다음 날";

        if (endTurnButtonImage != null)
            endTurnButtonImage.color = dungeonOpen ? ColorDungeonOpen : ColorNormalDay;
    }

    // ── 미궁 표시 ─────────────────────────────────────────────────────
    void OnDungeonUpdated(float remaining, float limit, int floor)
    {
        if (locationText != null) locationText.text = $"미궁 {floor}층";

        if (turnText != null)
            turnText.text = TurnManager.FormatHours(remaining);

        if (endTurnButtonLabel != null) endTurnButtonLabel.text = "대기 (1h)";

        if (endTurnButtonImage != null)
            endTurnButtonImage.color = (remaining / limit) > 0.25f ? ColorWait : ColorUrgent;
    }

    // ── 장소 전환 오버레이 ────────────────────────────────────────────
    void OnLocationChanging(GameLocation nextLocation)
    {
        if (transitionPanel == null) return;
        StopAllCoroutines();
        StartCoroutine(ShowTransition(nextLocation));
    }

    IEnumerator ShowTransition(GameLocation nextLocation)
    {
        bool goingToDungeon = nextLocation == GameLocation.Dungeon;

        if (transitionTitle != null)
            transitionTitle.text = goingToDungeon ? "미궁 입장" : "라프도니아로 복귀";

        if (transitionSub != null)
            transitionSub.text = goingToDungeon
                ? "미궁의 문이 열렸습니다."
                : "미궁 체류 시간이 모두 소진되었습니다.";

        transitionPanel.SetActive(true);
        if (endTurnButton != null) endTurnButton.gameObject.SetActive(false);

        yield return new WaitForSeconds(transitionDuration);

        transitionPanel.SetActive(false);
        if (endTurnButton != null) endTurnButton.gameObject.SetActive(true);
    }

    // ── 유닛 패널 ────────────────────────────────────────────────────
    void ShowUnitPanel(Unit unit)
    {
        if (unitPanel != null) unitPanel.SetActive(true);
        RefreshUnitPanel(unit);
        unit.OnStatsChanged -= RefreshUnitPanel;
        unit.OnStatsChanged += RefreshUnitPanel;
    }

    void HideUnitPanel()
    {
        if (unitPanel != null) unitPanel.SetActive(false);
    }

    void RefreshUnitPanel(Unit unit)
    {
        if (unit == null) return;
        if (unitNameText != null) unitNameText.text = unit.unitName;
        if (hpText       != null) hpText.text       = $"HP  {unit.CurrentHp} / {unit.maxHp}";
        if (moveText     != null) moveText.text      = $"이동력  {unit.MovesLeft} / {unit.maxMoveRange}";
        if (hpBar        != null) hpBar.value        = unit.HpRatio;
    }
}

