#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using TMPro;

/// <summary>
/// 에디터 메뉴 : DAS3D > Setup Scene
/// 한 번 실행하면 기본 씬 구조를 자동 생성합니다.
/// </summary>
public static class SceneSetup
{
    [MenuItem("DAS3D/Setup Scene")]
    public static void Setup()
    {
        // ── 1. 카메라 리그 ────────────────────────────────────────────
        GameObject cameraRig = new GameObject("CameraRig");
        cameraRig.AddComponent<GameCamera>();

        GameObject camGo = new GameObject("Main Camera");
        camGo.transform.SetParent(cameraRig.transform);
        var cam = camGo.AddComponent<Camera>();
        cam.tag = "MainCamera";
        cam.clearFlags = CameraClearFlags.Skybox;
        cam.nearClipPlane = 0.1f;
        cam.farClipPlane  = 500f;
        camGo.AddComponent<AudioListener>();

        // ── 2. 조명 ──────────────────────────────────────────────────
        GameObject lightGo = new GameObject("Directional Light");
        var light = lightGo.AddComponent<Light>();
        light.type = LightType.Directional;
        light.intensity = 1.2f;
        lightGo.transform.rotation = Quaternion.Euler(50f, -30f, 0f);

        // ── 3. GameManager ────────────────────────────────────────────
        GameObject gm = new GameObject("GameManager");
        gm.AddComponent<GridManager>();
        gm.AddComponent<UnitManager>();
        gm.AddComponent<TurnManager>();

        // ── 4. Canvas ─────────────────────────────────────────────────
        GameObject canvasGo = new GameObject("Canvas");
        var canvas = canvasGo.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.ScreenSpaceOverlay;
        var scaler = canvasGo.AddComponent<CanvasScaler>();
        scaler.uiScaleMode        = CanvasScaler.ScaleMode.ScaleWithScreenSize;
        scaler.referenceResolution = new Vector2(1920, 1080);
        canvasGo.AddComponent<GraphicRaycaster>();

        // EventSystem
        if (Object.FindFirstObjectByType<EventSystem>() == null)
        {
            GameObject esGo = new GameObject("EventSystem");
            esGo.AddComponent<EventSystem>();
            esGo.AddComponent<StandaloneInputModule>();
        }

        // ── 5. Unit Panel (하단 중앙) ─────────────────────────────────
        GameObject unitPanel = MakePanel(canvasGo.transform, "UnitPanel",
            anchorMin: new Vector2(0.3f, 0f), anchorMax: new Vector2(0.7f, 0f),
            pivot:     new Vector2(0.5f, 0f),
            anchoredPos: new Vector2(0f, 10f), size: new Vector2(0f, 140f));
        unitPanel.GetComponent<Image>().color = new Color(0f, 0f, 0f, 0.75f);

        var unitNameText = MakeText(unitPanel.transform, "UnitNameText", "유닛 이름", 20,
            TextAlignmentOptions.Center,
            new Vector2(0f, 1f), new Vector2(1f, 1f),
            new Vector2(10f, -35f), new Vector2(-10f, 0f));

        var hpText = MakeText(unitPanel.transform, "HpText", "HP 100 / 100", 15,
            TextAlignmentOptions.Center,
            new Vector2(0f, 1f), new Vector2(1f, 1f),
            new Vector2(10f, -65f), new Vector2(-10f, -35f));

        var moveText = MakeText(unitPanel.transform, "MoveText", "이동력 3 / 3", 15,
            TextAlignmentOptions.Center,
            new Vector2(0f, 1f), new Vector2(1f, 1f),
            new Vector2(10f, -90f), new Vector2(-10f, -60f));

        // HP Slider
        var slider = MakeSlider(unitPanel.transform,
            anchorMin: new Vector2(0.05f, 0f), anchorMax: new Vector2(0.95f, 0f),
            offsetMin: new Vector2(0f, 10f),   offsetMax: new Vector2(0f, 28f));

        // ── 6. Turn Panel (우하단) ─────────────────────────────────────
        GameObject turnPanel = MakePanel(canvasGo.transform, "TurnPanel",
            anchorMin: new Vector2(1f, 0f), anchorMax: new Vector2(1f, 0f),
            pivot:     new Vector2(1f, 0f),
            anchoredPos: new Vector2(-20f, 20f), size: new Vector2(220f, 130f));
        turnPanel.GetComponent<Image>().color = new Color(0.05f, 0.05f, 0.12f, 0.88f);

        var locationText = MakeText(turnPanel.transform, "LocationText", "라프도니아", 18,
            TextAlignmentOptions.Center,
            new Vector2(0f, 1f), new Vector2(1f, 1f),
            new Vector2(5f, -30f), new Vector2(-5f, 0f));
        locationText.color = new Color(0.9f, 0.8f, 0.4f); // 금색

        var turnText = MakeText(turnPanel.transform, "TurnText", "턴 1 / 5", 16,
            TextAlignmentOptions.Center,
            new Vector2(0f, 1f), new Vector2(1f, 1f),
            new Vector2(5f, -58f), new Vector2(-5f, -28f));

        var endTurnBtn = MakeButton(turnPanel.transform, "EndTurnButton", "턴 종료",
            anchorMin: new Vector2(0.08f, 0f), anchorMax: new Vector2(0.92f, 0f),
            offsetMin: new Vector2(0f, 10f),   offsetMax: new Vector2(0f, 58f),
            btnColor:  new Color(0.2f, 0.6f, 0.3f));

        // ── 7. Transition Panel (전체화면 장소 전환 알림) ─────────────
        GameObject transPanel = MakePanel(canvasGo.transform, "TransitionPanel",
            anchorMin: Vector2.zero, anchorMax: Vector2.one,
            pivot:     new Vector2(0.5f, 0.5f),
            anchoredPos: Vector2.zero, size: Vector2.zero);
        transPanel.GetComponent<Image>().color = new Color(0f, 0f, 0f, 0.82f);

        var transTitle = MakeText(transPanel.transform, "TransitionTitle", "라프도니아로 복귀", 42,
            TextAlignmentOptions.Center,
            new Vector2(0.1f, 0.5f), new Vector2(0.9f, 0.75f),
            Vector2.zero, Vector2.zero);
        transTitle.color = new Color(0.95f, 0.85f, 0.35f);

        var transSub = MakeText(transPanel.transform, "TransitionSub", "전투 턴이 모두 소진되었습니다.", 22,
            TextAlignmentOptions.Center,
            new Vector2(0.1f, 0.3f), new Vector2(0.9f, 0.5f),
            Vector2.zero, Vector2.zero);
        transSub.color = new Color(0.8f, 0.8f, 0.8f);

        transPanel.SetActive(false);

        // ── 8. GameUI 참조 연결 ───────────────────────────────────────
        var gameUI = gm.AddComponent<GameUI>();
        gameUI.unitPanel      = unitPanel;
        gameUI.unitNameText   = unitNameText;
        gameUI.hpText         = hpText;
        gameUI.moveText       = moveText;
        gameUI.hpBar          = slider;
        gameUI.locationText   = locationText;
        gameUI.turnText       = turnText;
        gameUI.endTurnButton  = endTurnBtn;
        gameUI.transitionPanel = transPanel;
        gameUI.transitionTitle = transTitle;
        gameUI.transitionSub   = transSub;

        Debug.Log("[DAS3D] 씬 세팅 완료!");
        EditorUtility.DisplayDialog("DAS3D Setup", "씬 세팅 완료!\n\n" +
            "• GameManager > TurnManager: raphdoniaMaxTurns / battleMaxTurns 조정\n" +
            "• GameManager > GridManager: width / height 조정\n" +
            "• UnitSpawner 를 GameManager 에 추가해 유닛 배치\n" +
            "• CameraRig > GameCamera: minBounds / maxBounds 맵 크기에 맞게 조정", "확인");
    }

    // ═══════════════════════════════════════════════════════════════════
    // 헬퍼
    // ═══════════════════════════════════════════════════════════════════

    static GameObject MakePanel(Transform parent, string name,
        Vector2 anchorMin, Vector2 anchorMax, Vector2 pivot,
        Vector2 anchoredPos, Vector2 size)
    {
        var go   = new GameObject(name);
        go.transform.SetParent(parent, false);
        go.AddComponent<Image>();
        var rt = go.GetComponent<RectTransform>();
        rt.anchorMin       = anchorMin;
        rt.anchorMax       = anchorMax;
        rt.pivot           = pivot;
        rt.anchoredPosition = anchoredPos;
        rt.sizeDelta       = size;
        return go;
    }

    static TMP_Text MakeText(Transform parent, string name, string text, int fontSize,
        TextAlignmentOptions alignment,
        Vector2 anchorMin, Vector2 anchorMax,
        Vector2 offsetMin, Vector2 offsetMax)
    {
        var go  = new GameObject(name);
        go.transform.SetParent(parent, false);
        var tmp = go.AddComponent<TextMeshProUGUI>();
        tmp.text      = text;
        tmp.fontSize  = fontSize;
        tmp.alignment = alignment;
        tmp.color     = Color.white;
        var rt = go.GetComponent<RectTransform>();
        rt.anchorMin = anchorMin;
        rt.anchorMax = anchorMax;
        rt.offsetMin = offsetMin;
        rt.offsetMax = offsetMax;
        return tmp;
    }

    static Button MakeButton(Transform parent, string name, string label,
        Vector2 anchorMin, Vector2 anchorMax,
        Vector2 offsetMin, Vector2 offsetMax, Color btnColor)
    {
        var go  = new GameObject(name);
        go.transform.SetParent(parent, false);
        var img = go.AddComponent<Image>();
        img.color = btnColor;
        var btn = go.AddComponent<Button>();
        var rt  = go.GetComponent<RectTransform>();
        rt.anchorMin = anchorMin;
        rt.anchorMax = anchorMax;
        rt.offsetMin = offsetMin;
        rt.offsetMax = offsetMax;

        // 버튼 라벨
        var labelGo = new GameObject("Label");
        labelGo.transform.SetParent(go.transform, false);
        var tmp = labelGo.AddComponent<TextMeshProUGUI>();
        tmp.text      = label;
        tmp.fontSize  = 17;
        tmp.alignment = TextAlignmentOptions.Center;
        tmp.color     = Color.white;
        var lrt = labelGo.GetComponent<RectTransform>();
        lrt.anchorMin = Vector2.zero;
        lrt.anchorMax = Vector2.one;
        lrt.offsetMin = lrt.offsetMax = Vector2.zero;

        return btn;
    }

    static Slider MakeSlider(Transform parent,
        Vector2 anchorMin, Vector2 anchorMax,
        Vector2 offsetMin, Vector2 offsetMax)
    {
        var go  = new GameObject("HpBar");
        go.transform.SetParent(parent, false);
        var slider = go.AddComponent<Slider>();
        slider.value = 1f;
        slider.minValue = 0f;
        slider.maxValue = 1f;
        var rt = go.GetComponent<RectTransform>();
        rt.anchorMin = anchorMin;
        rt.anchorMax = anchorMax;
        rt.offsetMin = offsetMin;
        rt.offsetMax = offsetMax;

        // Background
        var bg = new GameObject("Background");
        bg.transform.SetParent(go.transform, false);
        var bgImg = bg.AddComponent<Image>();
        bgImg.color = new Color(0.2f, 0.2f, 0.2f);
        var bgRt = bg.GetComponent<RectTransform>();
        bgRt.anchorMin = Vector2.zero;
        bgRt.anchorMax = Vector2.one;
        bgRt.offsetMin = bgRt.offsetMax = Vector2.zero;

        // Fill Area
        var fillArea = new GameObject("Fill Area");
        fillArea.transform.SetParent(go.transform, false);
        var faRt = fillArea.AddComponent<RectTransform>();
        faRt.anchorMin = Vector2.zero;
        faRt.anchorMax = Vector2.one;
        faRt.offsetMin = faRt.offsetMax = Vector2.zero;

        var fill = new GameObject("Fill");
        fill.transform.SetParent(fillArea.transform, false);
        var fillImg = fill.AddComponent<Image>();
        fillImg.color = new Color(0.2f, 0.8f, 0.3f);
        var fillRt = fill.GetComponent<RectTransform>();
        fillRt.anchorMin = Vector2.zero;
        fillRt.anchorMax = Vector2.one;
        fillRt.offsetMin = fillRt.offsetMax = Vector2.zero;

        slider.fillRect = fillRt;
        return slider;
    }
}
#endif

