        }

        // ── 2. Fonts 폴더 생성 및 폰트 복사 ──────────────────────────
        string absFontsDir  = Path.Combine(Application.dataPath, "Fonts");
        string absFontPath  = Path.Combine(Application.dataPath, "Fonts", "MalgunGothic.ttf");

        if (!Directory.Exists(absFontsDir))
            Directory.CreateDirectory(absFontsDir);

        File.Copy(WIN_FONT_PATH, absFontPath, overwrite: true);
        AssetDatabase.Refresh();

        // ── 3. Font 에셋 로드 ─────────────────────────────────────────
        Font font = AssetDatabase.LoadAssetAtPath<Font>(UNITY_FONT_PATH);
        if (font == null)
        {
            Debug.LogError("[DAS3D] 폰트 로드 실패: " + UNITY_FONT_PATH);
            return;
        }

        // ── 4. TMP FontAsset 생성 (Dynamic 모드 – 한글 온디맨드 로딩) ─
        TMP_FontAsset fontAsset = TMP_FontAsset.CreateFontAsset(
            font,
            samplingPointSize:    90,
            atlasPadding:         9,
            renderMode:           UnityEngine.TextCore.Text.GlyphRenderMode.SDFAA,
            atlasWidth:           1024,
            atlasHeight:          1024,
            atlasPopulationMode:  AtlasPopulationMode.Dynamic,
            enableMultiAtlasSupport: true);

        if (fontAsset == null)
        {
            Debug.LogError("[DAS3D] TMP_FontAsset 생성 실패");
            LogManualGuide();
            return;
        }

        // ── 5. 에셋 저장 ─────────────────────────────────────────────
        if (File.Exists(Path.Combine(Application.dataPath, "..", UNITY_SDF_PATH)))
            AssetDatabase.DeleteAsset(UNITY_SDF_PATH);

        AssetDatabase.CreateAsset(fontAsset, UNITY_SDF_PATH);
        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();

        // ── 6. TMP 기본 폰트로 설정 ───────────────────────────────────
        TMP_Settings settings = TMP_Settings.instance;
        if (settings != null)
        {
            var so   = new SerializedObject(settings);
            var prop = so.FindProperty("m_defaultFontAsset");
            if (prop != null)
            {
                prop.objectReferenceValue = fontAsset;
                so.ApplyModifiedProperties();
                EditorUtility.SetDirty(settings);
                AssetDatabase.SaveAssets();
                Debug.Log("[DAS3D] TMP 기본 폰트 → 맑은 고딕 설정 완료");
            }
            else
            {
                Debug.LogWarning("[DAS3D] TMP_Settings 프로퍼티를 찾지 못했습니다. 수동으로 설정하세요.");
            }
        }

        EditorUtility.DisplayDialog("완료",
            "한글 폰트 설정 완료!\n\n" +
            "맑은 고딕이 TMP 기본 폰트로 설정되었습니다.\n\n" +
            "적용 방법:\n" +
            "1. DAS3D > Setup Scene 을 다시 실행하거나\n" +
            "2. 기존 씬의 TMP_Text 컴포넌트에서\n   Font Asset 을 MalgunGothic_SDF 로 교체", "확인");
    }

    static void LogManualGuide()
    {
        Debug.Log(
            "[DAS3D] ═══ 한글 폰트 수동 설치 가이드 ═══\n" +
            "1. Window > TextMeshPro > Font Asset Creator 열기\n" +
            "2. Source Font File: 시스템 폰트 목록에서 'Malgun Gothic' 선택\n" +
            "   (없으면 C:\\Windows\\Fonts\\malgun.ttf 를 Assets/Fonts/ 에 직접 복사)\n" +
            "3. Atlas Population Mode: Dynamic\n" +
            "4. Generate Font Atlas 클릭\n" +
            "5. Save 로 Assets/Fonts/MalgunGothic_SDF.asset 저장\n" +
            "6. Window > TextMeshPro > Settings 열기\n" +
            "7. Default Font Asset 을 MalgunGothic_SDF 로 변경\n" +
            "8. DAS3D > Setup Scene 재실행");
    }
}
#endif

